argv:
$targets = @(
  @{name='media'; id='312D0941F3A5138C71E55254EAEBBEC8'},
  @{name='creator'; id='B0559FFE7843B036079007016E7351FF'},
  @{name='growth'; id='DBC6BC28E04127D1821830B232E048EB'},
  @{name='bridge'; id='A88E3157A8078B7DA32FC62848071CC3'},
  @{name='mcp'; id='9BAA48607EDE0A4DFA73EAD8396BA451'}
)
$raw=(Invoke-WebRequest -UseBasicParsing -Uri 'http://127.0.0.1:17410/json/list' -TimeoutSec 5).Content
$list=$raw|ConvertFrom-Json
$out=@()
foreach($x in $targets){
  $t=@($list)|Where-Object{$_.id -eq $x.id}|Select-Object -First 1
  if($t){$out += [pscustomobject]@{name=$x.name;id=$t.id;title=$t.title;url=$t.url;open=$true}}
  else{$out += [pscustomobject]@{name=$x.name;id=$x.id;title='';url='';open=$false}}
}
$out|ConvertTo-Json -Compress -Depth 3
